// Copies data the game takes straight from main.dol (the caution screen's archive, font and messages)
// out of the disc's DOL into the arrays generated by tools/gen_pc_dol_data.py.
#include <revolution/dvd.h>

#include <borealis/log_c.h>

#include <string.h>

namespace cf {

struct DolBlob {
    const char* name;
    u8* dst;
    u32 address;
    u32 size;
};

// Generated (tools/gen_pc_dol_data.py)
extern const DolBlob kDolBlobs[];
extern const size_t kDolBlobCount;

namespace {

u32 ReadBE32(const u8* p) {
    return (u32(p[0]) << 24) | (u32(p[1]) << 16) | (u32(p[2]) << 8) | u32(p[3]);
}

// A DOL header: 7 text and 11 data sections, as file offsets, load addresses and sizes
constexpr int DOL_SECTIONS = 18;
constexpr size_t DOL_HEADER_SIZE = 0x100;

const u8* FindInDol(const u8* dol, size_t dolSize, u32 address, u32 size) {
    for (int i = 0; i < DOL_SECTIONS; i++) {
        u32 offset = ReadBE32(dol + i * 4);
        u32 start = ReadBE32(dol + 0x48 + i * 4);
        u32 length = ReadBE32(dol + 0x90 + i * 4);
        if (length != 0 && address >= start && address - start + size <= length) {
            size_t fileOffset = size_t(offset) + (address - start);
            return fileOffset + size <= dolSize ? dol + fileOffset : nullptr;
        }
    }
    return nullptr;
}

} // namespace

// Call after aurora_dvd_open and before the game starts. Returns false if anything is missing.
bool LoadDolData() {
    s32 dolSize = 0;
    const u8* dol = DVDGetDOLLocation(&dolSize);
    if (dol == nullptr || dolSize < static_cast<s32>(DOL_HEADER_SIZE)) {
        borealis_log_printf(BOREALIS_LOG_ERROR, "cf::dol", "main.dol is not available from the disc");
        return false;
    }

    bool ok = true;
    for (size_t i = 0; i < kDolBlobCount; i++) {
        const DolBlob& blob = kDolBlobs[i];
        const u8* src = FindInDol(dol, static_cast<size_t>(dolSize), blob.address, blob.size);
        if (src == nullptr) {
            borealis_log_printf(BOREALIS_LOG_ERROR, "cf::dol", "%s (0x%08X, 0x%X bytes) is not in main.dol",
                                blob.name, blob.address, blob.size);
            ok = false;
            continue;
        }
        memcpy(blob.dst, src, blob.size);
    }

    return ok;
}

} // namespace cf
